// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Write frames -- per component, the global frame constrains every
//! SystemState field outside the component's write set to be unchanged
//! across its firing; the local frame is `true`.

#![allow(non_snake_case)]

use vstd::prelude::*;

use crate::system_state::SystemState;

verus! {

/** OUTER_A writes: system_output.
  * Everything else must be unchanged.
  */
pub open spec fn outer_a_global_write_frame(pre: SystemState, post: SystemState) -> bool
{
  pre.system_input == post.system_input
  && pre.top_a_output == post.top_a_output
  && pre.top_b_output == post.top_b_output
  && pre.top_output == post.top_output
}

/** OUTER_A local write frame: the component may modify anything in its
  * own scope (Isabelle `lFrame := (λ_ _. True)`).
  */
pub open spec fn outer_a_local_write_frame(pre: SystemState, post: SystemState) -> bool
{
  true
}

/** A writes: top_a_output.
  * Everything else must be unchanged.
  */
pub open spec fn a_global_write_frame(pre: SystemState, post: SystemState) -> bool
{
  pre.system_output == post.system_output
  && pre.system_input == post.system_input
  && pre.top_b_output == post.top_b_output
  && pre.top_output == post.top_output
}

/** A local write frame: the component may modify anything in its
  * own scope (Isabelle `lFrame := (λ_ _. True)`).
  */
pub open spec fn a_local_write_frame(pre: SystemState, post: SystemState) -> bool
{
  true
}

/** B writes: top_b_output.
  * Everything else must be unchanged.
  */
pub open spec fn b_global_write_frame(pre: SystemState, post: SystemState) -> bool
{
  pre.system_output == post.system_output
  && pre.system_input == post.system_input
  && pre.top_a_output == post.top_a_output
  && pre.top_output == post.top_output
}

/** B local write frame: the component may modify anything in its
  * own scope (Isabelle `lFrame := (λ_ _. True)`).
  */
pub open spec fn b_local_write_frame(pre: SystemState, post: SystemState) -> bool
{
  true
}

/** C writes: top_output.
  * Everything else must be unchanged.
  */
pub open spec fn c_global_write_frame(pre: SystemState, post: SystemState) -> bool
{
  pre.system_output == post.system_output
  && pre.system_input == post.system_input
  && pre.top_a_output == post.top_a_output
  && pre.top_b_output == post.top_b_output
}

/** C local write frame: the component may modify anything in its
  * own scope (Isabelle `lFrame := (λ_ _. True)`).
  */
pub open spec fn c_local_write_frame(pre: SystemState, post: SystemState) -> bool
{
  true
}

} // verus!
